import math

def is_multiply_prime(a):
    """Returns True if the given number is the multiplication of 3 prime numbers, False otherwise."""
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(math.sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    for i in range(2, int(a ** (1/3)) + 1):
        if a % i == 0:
            for j in range(i, int((a // i) ** (1/2)) + 1):
                if (a // i) % j == 0:
                    k = (a // i) // j
                    if is_prime(i) and is_prime(j) and is_prime(k):
                        return True
    return False
